function marketPanel(stash=false){const s=g.s,p=s.players[viewer],price=stash?1:2,allowed=stash?g.canLastStand(viewer):s.phase==='shop'&&s.shopTurn===viewer,canBuy=allowed&&p.coins>=price&&p.loot.length<2,blind=(s.lootSupply??(s.lootDeck.length+s.lootDiscard.length))>0;return `<section class="loot-market" aria-label="Shared Loot market"><div class="market-heading"><div><p class="eyebrow">SHARED LOOT · ${price} COINS EACH</p><h2>${stash?'Emergency Stash':'The spoils of Brawl'}</h2><p>${allowed?'Choose one face-up item, or take a blind draw.':s.phase==='shop'?short(s.players[s.shopTurn].hero)+' buys next.':'Shop between rounds. Anyone can use these items.'} · ${p.coins} Coins · Held ${p.loot.length}/2${allowed&&!canBuy?p.loot.length>=2?' · Your Loot hand is full':' · Need '+price+' Coins':''}</p></div><button data-market-buy="blind" data-stash="${stash}" ${!canBuy||!blind?'disabled':''}>Blind draw · ${price} Coins</button></div><div class="market-offers">${s.market.map(id=>`<article>${card(def(id))}<button class="primary" data-market-buy="${id}" data-stash="${stash}" ${!canBuy?'disabled':''}>Buy ${esc(def(id).name)} · ${price} Coins</button></article>`).join('')}</div>${allowed&&!stash?'<button data-action="save-coins">Keep my Coins · continue →</button>':''}<p class="small muted">Bought offers refill immediately. Spent Loot reshuffles when needed. One purchase each between rounds; new Edge buys first.</p></section>`;}
function setup(){
 drafts[editor+'-'+ids[editor]]={deck:[...decks[editor]],fury:furies[editor],build:buildIds[editor],loot:[...lootPicks[editor]]};try{localStorage.setItem(DRAFT_SAVE,JSON.stringify(drafts));}catch{}
 const h=hero(ids[editor]),join=invitation().invite,list=decks[editor],counts={attacks:list.filter(id=>def(id).attackText).length,reactions:list.filter(id=>def(id).reactionText).length,coins:list.filter(id=>def(id).category==='Basic'&&def(id).attackText).length};
 const valid=!(mode==='online'?[0]:[0,1]).some(i=>(!Brawl2.validDeck(data,ids[i],decks[i])||!Brawl2.validLoot(data,ids[i],lootPicks[i]))),build=data.builds.find(b=>b.id===buildIds[editor]);let saved=false;try{saved=!!localStorage.getItem(SAVE);}catch{}
 app.innerHTML=`<section class="setup r-setup od-setup"><div class="r-intro"><p class="eyebrow">ONE DECK · TWO SECRET ATTACKS · YOUR ANSWERS IN HAND</p><h1>Build your fight.</h1><p>Choose 24 cards. Pick your Fury.<br>Every card you spend is a choice.</p></div><div class="r-setup-grid"><section class="r-hero-select"><div class="r-hero-stage"><img src="${art(h.id)}" alt="${esc(h.name)}"><div><p class="eyebrow">${esc(h.archetype)}</p><h2>${esc(h.name)}</h2></div></div><div class="r-roster">${data.heroes.map(h=>`<button data-hero="${h.id}" class="${ids[editor]===h.id?'active':''}" aria-label="Choose ${esc(h.name)}"><img src="${art(h.id)}" alt=""><b>${short(h.id)}</b></button>`).join('')}</div><div class="r-trait"><b>${esc(h.trait)}</b><p>${esc(h.traitText)}</p><button class="quiet" data-guide="${h.id}">Hero field guide ↗</button></div><h3 class="od-fury-heading">Choose your Fury</h3><p class="small muted">Outside your 24 cards. Unlock into your hand at 10 Health.</p><div class="od-fury-choices">${h.furies.map(id=>{const c=def(id);return `<div class="${furies[editor]===id?'active':''}"><button data-fury="${id}" aria-pressed="${furies[editor]===id}"><b>${furies[editor]===id?'✦ ':''}${esc(c.name)}</b><span>${esc(c.attackText)} · Speed ${c.speed}</span></button><button class="quiet" data-inspect="${id}" aria-label="Read ${esc(c.name)}">Read</button></div>`;}).join('')}</div></section><section class="r-deck"><div class="segment">${['solo','hotseat',...(canOnline?['online']:[])].map(m=>`<button data-mode="${m}" class="${mode===m?'active':''}">${m==='solo'?'Vs computer':m==='hotseat'?'Pass & play':'Online duel'}</button>`).join('')}</div>${join?'<p class="r-invite-note">Private invitation: build your deck, then join your rival.</p>':''}<div class="r-deck-title"><div class="segment">${(mode==='online'?[0]:[0,1]).map(i=>`<button data-editor="${i}" class="${editor===i?'active':''}">${i===0?'YOUR DECK':mode==='solo'?'COMPUTER':'PLAYER 2'} · ${short(ids[i])}</button>`).join('')}</div></div><label class="od-build-label">Starting build<select data-build aria-label="Starting build"><option value="custom" ${!build?'selected':''}>Custom deck</option>${data.builds.filter(b=>b.hero===h.id).map(b=>`<option value="${b.id}" ${build?.id===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select></label>${build?`<p class="od-build-plan">${esc(build.plan)}</p><p class="small muted"><b>Tradeoff:</b> ${esc(build.weakness)}</p>`:'<p class="od-build-plan">Any 24 from your 40-card pool. No Basic or Hero quotas.</p>'}<div class="od-deck-counts" aria-live="polite"><b>${list.length}/24 CARDS</b><span>${counts.attacks} can attack</span><span>${counts.reactions} can react</span><span>${counts.coins} earn Coins</span></div><p class="small muted">Dual cards count in both options, but you play only one half.</p>${lootDraft(h)}<div class="r-start"><button class="primary" data-action="start" ${busy||!valid?'disabled':''}>${busy?'Connecting…':mode==='online'?join?'Join private duel →':'Create private duel →':'Start the fight →'}</button>${saved&&mode!=='online'?'<button data-action="resume">Resume</button>':''}</div><div class="od-draft-tools"><button data-action="random">Random 24</button><button data-action="clear-deck">Clear deck</button><button data-action="view-draft">Review selected cards</button></div><p class="small muted">Your deck choices are saved in this browser.</p><details class="od-custom-pool" ${build?'':'open'}><summary>Customize your 24 · view all 20 designs</summary><p class="small muted">Two copies of every design are available. Basic Attack halves earn 1 Coin (2 for Franc on a damaging hit). Other cards grant Coins only when printed.</p><div class="od-pool-grid">${h.pool.map(id=>pool(def(id),list)).join('')}</div></details><p class="r-footnote">20 Health · 8 arena spaces · Draw 7 · Refill up to 4, stop at 7<br>Loot costs 2 · Fury at 10 Health · Last Stand at 5<br><a href="/brawl" target="_blank" rel="noopener">Original Brawl ↗</a></p></section></div></section>`;
}
function privateActor(){const s=g.s;if(s.phase==='program')return s.committed.findIndex(x=>!x);if(s.prompt)return s.prompt.player;if(s.phase==='reaction')return s.turn;if(s.phase==='shop')return s.shopTurn;return -1;}
function passive(p){return {SMA:'Wall slams: 3 damage',ALF:'Bullseye · damaging hit at Range 3+: draw 1',SHE:'Pay Health for a card: draw 1',HEL:'Shield Up · gain 1 Block when rival attacks',RAV:'First crossing: +2 damage on your attack',FRA:'Damaging Basic Attack: +1 extra Coin',MAR:'Block a strike → earn Formation',SIB:'Commit a spear before reactions · +2 damage',VER:'Hit → ready a Technique · reuse a Dual Reaction',MEI:'Hero attacks lay Wind · consume it for +2 movement'}[p.hero];}
function hud(i){const s=g.s,p=s.players[i],attacking=s.active===i&&['pre','reaction','resolve'].includes(s.phase);return `<section class="r-hud ${i?'right':''} ${attacking?'t-attacking':''} ${p.ultimate?'ls-hud-active ls-hud-'+p.hero:''}" data-hud-player="${i}"><button data-guide="${p.hero}" data-player="${i}" aria-label="View ${esc(p.name)} abilities"><img src="${fighterArt(p)}" alt=""></button><div><span class="eyebrow">${mode==='online'?viewer===i?'YOU':'ONLINE RIVAL':i===0?'PLAYER 1':mode==='solo'?'COMPUTER':'PLAYER 2'}${attacking?' · ATTACKING':''}</span><h2><button class="stage-hero-name" data-guide="${p.hero}" data-player="${i}">${esc(p.name)}</button></h2><div class="r-hp"><span style="width:${p.hp/MAX_HEALTH*100}%"></span></div><div class="r-resources"><b>${p.hp}/${MAX_HEALTH} HP</b><span>● ${p.coins} Coins${s.lastCoin?.player===i&&s.lastCoin.amount?`<small class="t-coin"> +${s.lastCoin.amount}</small>`:''}</span><span>◇ ${p.block} Block</span><span class="${p.ultimate?'fury-on':''}">${p.ultimate?'✦ LAST STAND':p.skillUnlocked?'✦ FURY UNLOCKED':'FURY AT 10 HP'}</span></div><p class="r-passive">${esc(passive(p))}</p>${tokenHud(i)}${p.ultimate?`<div class="ls-power"><strong>LAST STAND</strong><span>${esc(hero(p.hero).ultimate.name)}</span><small>${esc(lastStandStatus({...p,pinned:false}))}</small></div>`:''}<span class="ls-status ${p.ultimate?'active':''} ${p.pinned?'pinned':''}">${esc(lastStandStatus(p))}</span><button class="quiet od-fury-link" data-inspect="${p.furyId}">${esc(def(p.furyId).name)} · ${p.skillUnlocked?'unlocked':'locked'}</button></div></section>`;}
function plan(i){const s=g.s;return `<div class="r-plan"><span>${short(s.players[i].hero)} ${s.committed[i]?'· LOCKED':'· CHOOSING'}</span>${[0,1].map(k=>{const c=s.plans[i]?.[k]||(i===viewer?s.players[i].hand.find(c=>c.uid===selected[k]):null);return `<b class="${c?'filled':''}">${k+1} ${c&&i===viewer?esc(def(c)?.name||'Hidden'):c?'✦':'…'}</b>`;}).join('')}</div>`;}
function threat(){const f=forecast(g);if(!f)return '';const target=short(g.s.players[1-g.s.active].hero),loss=f.loss===f.maxLoss?f.loss:f.loss+'–'+f.maxLoss;return `<div class="t-threat ${f.miss?'safe':'danger'}"><small>IF BOTH PASS NOW</small><b>${f.miss?'Attack misses — out of range':target+' takes '+loss+' damage'}</b><span>${f.hits.map(h=>h.miss?'Out of range':h.damage+' damage − '+h.blocked+' Block'+' = '+h.loss+' damage'+(h.pierce?' · ignores Block':'')).join('<br>')}</span><span>Distance ${f.distance} · ${f.hits.length>1?'each hit checked separately':'Range '+g.attackInfo().hits.map(h=>h.min+'–'+h.max).join(' / ')}</span>${f.payment.length?f.payment.map(p=>`<small>Optional payment at resolution: ${p.cost} ${p.resource==='hp'?'Health':p.resource==='coins'?'Coins':'Block'} for +${p.bonus} damage. ${f.optional?'Potential bonus included in the damage range above.':'Currently unaffordable.'}</small>`).join(''):''}${def(g.s.mains[g.s.active]).ops.some(o=>o.op==='push')||g.s.mods[g.s.active].push?'<small>On-hit push may add a wall slam; choose the distance after the hit.</small>':''}</div>`;}
function resultPanel(){const r=g.s.lastResult;if(!r||!r.hits.length&&!r.walls.length&&!r.coin)return '';return `<div class="t-result"><b>${esc(r.name)} · RESULT</b>${r.hits.map(h=>`<span>${h.miss?'Missed at distance '+h.distance:h.damage+' damage − '+h.blocked+' Block'+' = '+h.loss+' damage'+(h.pierce?' · ignores Block':'')}</span>`).join('')}${r.walls.map(w=>`<span>WALL SLAM · +${w.damage} damage</span>`).join('')}${r.coin?`<span class="t-coin">+${r.coin} Coin${r.coin===1?'':'s'} · Basic Attack</span>`:''}</div>`;}
function refillPanel(){const r=g.s.lastRefill[viewer];if(!r||!['program','shop'].includes(g.s.phase))return '';return `<div class="t-refill"><b>YOUR REFILL · ROUND ${r.round}</b><span>Kept ${r.kept} + drew ${r.drawn} = ${r.total} cards</span><small>One draw pile · draw up to 4, stopping at 7 · Loot held separately</small></div>`;}
function legacyFlowPanel(){const step=combatStep(g,viewer),s=g.s,f=['reaction'].includes(s.phase)?forecast(g):null;return `<div class="t-flow" role="status" aria-live="polite"><div><p class="eyebrow">${esc(step.label)}</p><strong>${esc(step.title)}</strong><p>${esc(step.detail)}</p></div>${f?`<div class="t-flow-outcome">If both pass now:<b>${f.miss?'Attack misses':short(s.players[1-s.active].hero)+' takes '+(f.loss===f.maxLoss?f.loss:f.loss+'–'+f.maxLoss)+' damage'}</b>${f.reflection?'<span>Spiked shield reflects 1 damage to attacker.</span>':''}${s.passes===1?`<span>${s.turn===viewer?'LAST CHANCE TO REACT':'OPPONENT’S LAST CHANCE'}</span>`:''}</div>`:''}<div class="od-flow-actions">${controls()}</div></div>`;}
function flowPanel(){
 const s=g.s,step=combatStep(g,viewer),f=s.phase==='reaction'?forecast(g):null;
 let title=step.title,detail=step.detail;
 if(s.phase==='program'){title=s.committed[viewer]?'Your attacks are locked':`Choose ${g.requiredAttacks(viewer)} attacks`;detail=s.committed[viewer]?'Waiting for your rival':'Click in order · click again to return a card';}
 if(s.phase==='reaction'){title=s.turn===viewer?'Your reaction':`${short(s.players[s.turn].hero)} is reacting`;detail=s.passes===1?'One pass · another pass resolves the attack':'Play a Reaction or Loot, or pass';}
 if(s.prompt&&s.prompt.player===viewer){const q=s.prompt,key=(q.task||q).key;if(q.kind==='token'){title={spear:'Commit a War Spear?',pierce:'Break through their guard?',march:'Advance behind your shield?',guard:'Sacrifice a spear to block?',guardChoice:'Find your opening',windMove:'Ride the Wind?',windDamage:'Charge your Sky-Cutting Sword?',windMinimum:'Bring the blade closer?'}[key]||'Choose your token effect';detail=key==='spear'?'Spent even on a miss · choose damage or reach':q.title;}else if(['wind-place','wind-replace'].includes(q.kind)){title=q.kind==='wind-place'?'Lay your next Wind Current':'Relocate a Wind Current';detail='Click a highlighted arena space'+(q.kind==='wind-place'?' · or keep your markers':'');}}
 if(s.prompt?.kind==='tempo'&&s.prompt.player===viewer){const q=s.prompt,t=q.task||q,current=g.speed(viewer),other=g.speed(1-viewer),boosted=current+t.speed;detail=`Speed ${current} → ${boosted} · ${boosted>other||boosted===other&&s.edge===viewer?'You would attack first':short(s.players[1-viewer].hero)+' would still attack first'}`;}
 const automatic=autoFlow&&mode!=='hotseat'&&['reveal','result'].includes(s.phase)&&!s.prompt;
 return `<div class="stage-cue" role="status" aria-live="polite"><span>${s.phase==='program'?'MAKE YOUR PLAN':s.phase==='shop'?'BETWEEN ROUNDS':s.phase==='over'?'FIGHT FINISHED':'PAIR '+(s.reveal+1)+' · '+(s.active===null?'REVEAL':esc(def(s.mains[s.active])?.name||'CHOICE'))}</span><strong>${esc(title)}</strong><small>${esc(detail)}</small></div>${f?`<div class="stage-forecast ${f.miss?'safe':''}"><span>IF BOTH PASS</span><b>${f.miss?'OUT OF RANGE':(f.loss===f.maxLoss?f.loss:f.loss+'–'+f.maxLoss)+' DAMAGE'}</b><small>${short(s.players[1-s.active].hero)}${f.reflection?' · reflects 1':''}</small></div>`:''}<div class="stage-controls ${automatic?'stage-auto':''}">${automatic?'<span class="stage-playing">✦ Playing the exchange</span>':controls()}</div>`;
}
function battleMenu(){modal(`<p class="eyebrow">FABLE FURY · BRAWL</p><h2>At your fingertips</h2><div class="stage-menu"><button data-action="my-deck">Your deck</button><button data-action="market">Loot market</button><button data-action="log">Battle log</button><button data-action="rules">Rules & cards</button><button data-action="pace">${autoFlow?'Switch to manual pacing':'Switch to automatic flow'}</button><button data-action="sound">${audio.enabled?'Mute sound':'Enable sound'}</button><button data-action="mix">Audio mix</button><button data-action="fullscreen">Fullscreen</button><button data-action="new">Leave fight / new match</button></div><p class="small muted">Escape closes this menu. Decisions wait for you.</p>`);}
function tokenIcon(id){const paths={MAR:'M12 2 3 6v7c0 5 9 9 9 9s9-4 9-9V6Z M7 10h10M12 6v11',SIB:'M5 21 17 5M13 5l8-3-1 9-3-6Z M7 14l4 3',VER:'M4 21 18 3l3-1-1 6L7 22Z M3 16l6 5',MEI:'M3 8h12c6 0 6-6 2-6M2 12h17c5 0 4 7 0 7M5 16h7c4 0 4 6 0 6'};return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[id]}"/></svg>`;}
function tokenHud(i){const p=g.s.players[i];if(p.tokens===undefined)return '';const ready=p.tokens,actions=i===viewer?g.tokenActions(i):[],label=hero(p.hero).trait;return `<button class="core-token-rack core-token-${p.hero} ${actions.length?'ready':''}" ${actions.length?'data-action="hero-ability"':`data-guide="${p.hero}" data-player="${i}"`} aria-label="${label}: ${ready} of 3 ${p.hero==='MEI'?'in supply':'ready'}. ${actions.length?'Use tokens':'View rules'}" title="${esc(hero(p.hero).traitText)}"><span class="core-token-pips">${[0,1,2].map(k=>`<i class="${k<ready?'charged':'empty'}">${tokenIcon(p.hero)}</i>`).join('')}</span><span><b>${esc(label)}</b><small>${ready}/3 ${p.hero==='MEI'?'in supply'+(p.wind.length?' · spaces '+p.wind.join(', '):''):'ready'}${actions.length?' · USE':''}</small></span></button>`;}
function abilityButton(){return g.tokenActions(viewer).map(a=>`<button class="ls-action core-ability" data-ability-card="${a.id}" title="${esc(a.text)}">${esc(a.label)}</button>`).join('');}
function abilityPicker(){const h=hero(g.s.players[viewer].hero);modal(`<p class="eyebrow">HERO TOKENS</p><h2>${esc(h.trait)}</h2><p>${esc(h.traitText)}</p><div class="core-token-options">${g.tokenActions(viewer).map(a=>`<button data-ability-card="${a.id}"><b>${esc(a.label)}</b><span>${esc(a.text)}</span></button>`).join('')}</div>`);}
function controls(){const s=g.s;if(s.phase==='over')return `${resultPanel()}<p class="eyebrow">${s.winner==='draw'?'DOUBLE KNOCKOUT':'VICTORY'}</p><h3>${s.winner==='draw'?'What a finish.':short(s.players[s.winner].hero)+' wins!'}</h3><button class="primary" data-action="new">Play another fight</button>`;
 if(s.prompt){const q=s.prompt;if(q.player!==viewer)return '<p>Your rival is choosing…</p>';if(['scry','discard','recover','stash'].includes(q.kind))return '<span class="x-private-label">◈ PRIVATE CHOICE</span>';const payment=['tempo','invest','pay'].includes(q.kind);return `<div class="r-choices">${['move','wind-replace'].includes(q.kind)?'':q.choices.map((v,k)=>q.kind==='wind-place'&&v!==0?'':`<button class="${(v&&payment)||(q.kind==='token'&&v!=='skip')?'primary':''}" data-choice-index="${k}">${q.kind==='token'?esc((q.task?.labels||q.labels||{})[v]||v):payment?v?'Pay & '+(q.kind==='tempo'?'gain Speed':'power up'):'Keep resources':v===0?'Keep current markers':v+(['wind-place','wind-replace'].includes(q.kind)?' · arena space':v===1?' space':' spaces')}</button>`).join('')}</div>`;}
 if(s.phase==='program'){const n=g.requiredAttacks(viewer);return s.committed[viewer]?'<p class="eyebrow">ATTACKS LOCKED</p><h3>Keep your answers ready.</h3><p>Uncommitted cards stay in your hand.</p>':`<p class="eyebrow">${selected.length}/${n} ATTACKS CHOSEN</p><h3>${n===0?'No Attacks this round.':selected.length===n?'That’s your plan.':n===1?'Choose your Attack.':'Choose two Attacks.'}</h3><p>${n<2?'You can still react to your rival’s Attacks. No replacement draw.':'Click in order. A dual card committed here cannot also react.'}</p><button class="primary" data-action="commit" ${selected.length!==n?'disabled':''}>${n===0?'Ready without attacks →':`Lock ${n===1?'one Attack':'two Attacks'} →`}</button>${abilityButton()}${selected.length===2?'<button class="quiet" data-action="swap">⇄ Swap order</button>':''}`;}
 if(s.phase==='reveal')return `<p class="eyebrow">PAIR ${s.reveal+1} REVEALED</p><h3>${short(s.players[s.order[0]].hero)} attacks first.</h3><p>Speed sets order. Each attack gets its own reaction exchange.</p><button class="primary" data-action="advance">Activate attack →</button>`;
 if(s.phase==='reaction')return `<p class="eyebrow">${s.turn===viewer?'YOUR REACTION TURN':short(s.players[s.turn].hero).toUpperCase()+' IS REACTING'} · ${s.passes}/2 PASSES</p><h3>${s.turn===viewer?s.active===viewer?'Make it connect.':'Answer the attack.':'Your rival’s answer…'}</h3>${threat()}<p>${s.turn===viewer?s.passes===1?'Your opponent passed. Pass to resolve, or play another card.':'Click one usable Reaction or Loot below. Playing a card resets the pass count.':'Your hand stays visible to you. Wait for your turn.'}</p>${s.turn===viewer?`${g.s.players[viewer].ultimate&&['RAV','FRA'].includes(g.s.players[viewer].hero)?`<button class="ls-action" data-action="last-stand" ${g.canLastStand(viewer)?'':'disabled'}>${g.s.players[viewer].hero==='RAV'?'⇄ Shadow swap · '+(g.s.players[viewer].shadowUsed?'used this round':'once per round'):'✦ Buy Loot · 1 Coin'}</button>`:''}${abilityButton()}<button class="primary" data-action="pass">${s.passes===1?'Pass & resolve attack →':'Pass priority →'}</button>`:''}<p class="t-no-draw">Draw only when a card or passive says so.</p>`;
 if(s.phase==='result')return `${resultPanel()}<p class="eyebrow">${esc(def(s.mains[s.active]).name)} RESOLVED</p><h3>${s.attackIndex+1<s.order.length?short(s.players[s.order[s.attackIndex+1]].hero)+' attacks next.':s.reveal===0?'The next pair awaits.':'Round done. Fresh answers.'}</h3><button class="primary" data-action="advance">${s.attackIndex+1<s.order.length?'Activate other attack →':s.reveal===0?'Flip second Attacks →':'Refill & next plan →'}</button>`;
 if(s.phase==='shop')return s.shopTurn!==viewer?'<h3>Your rival is deciding…</h3>':`<p class="eyebrow">ROUND COMPLETE</p><h3>Pick your next trick.</h3><button class="primary" data-action="market">Browse market · 2 Coins</button><button data-action="save-coins">Save Coins →</button>`;return '<h3>Resolving…</h3>';}

function phaseTrack(){const s=g.s,stage=s.phase==='program'?0:s.phase==='shop'?3:s.phase==='over'?4:s.reveal+1;return `<div class="x-phase-track" aria-label="Round progress">${['Plan','First pair','Second pair','Refill & Loot'].map((t,i)=>`<span class="${i===stage?'current':i<stage?'done':''}">${i<stage?'✓':i+1} ${t}</span>`).join('')}</div>`;}
function choicePanel(){const q=g.s.prompt;if(!q||q.player!==viewer)return '';if(q.kind==='stash')return `<section class="x-choice"><div><p class="eyebrow">EMERGENCY STASH</p><h3>A free surprise?</h3><p>Keep your two Loot, or replace one with a blind draw.</p><button data-choice-index="0">Keep both Loot</button></div><div class="ls-stash-choice">${g.s.players[viewer].loot.map((id,k)=>`<button data-choice-index="${k+1}"><b>Replace ${esc(def(id).name)}</b>${card(def(id))}</button>`).join('')}</div></section>`;if(!['scry','discard','recover'].includes(q.kind))return '';const p=g.s.players[viewer],cards=q.kind==='scry'?(q.cards||q.task?.cards||[]):(q.kind==='recover'?p.discard:p.hand).filter(c=>q.choices.includes(c.uid));const key=q.kind+':'+cards.map(c=>c.uid).join(',');if(key!==scryKey){scryKey=key;scryOrder=[];}
 return `<section class="x-choice" aria-label="${q.kind} choice"><div><p class="eyebrow">${q.kind==='scry'?'PREPARE YOUR NEXT DRAW':q.kind==='recover'?'RETURN A PLAYED BASIC':'CHOOSE A CARD TO DISCARD'}</p><h3>${q.kind==='scry'?'A little foresight. A very big shot.':q.kind==='recover'?'Give it another go.':'What can you spare?'}</h3><p>${q.kind==='scry'?'Click cards in the order you want to draw them. Unselected cards go to the bottom. This does not draw a card.':esc(q.title)}</p>${q.kind==='scry'?`<button class="primary" data-action="scry-confirm">${scryOrder.length?'Keep '+scryOrder.length+' on top →':'Put all on bottom →'}</button>`:''}</div><div class="x-choice-cards">${cards.map(c=>`<div><button class="x-choice-pick ${scryOrder.includes(c.uid)?'chosen':''}" ${q.kind==='scry'?`data-scry-uid="${c.uid}" aria-pressed="${scryOrder.includes(c.uid)}"`:`data-choice-index="${q.choices.indexOf(c.uid)}"`}><strong>${q.kind==='scry'?scryOrder.includes(c.uid)?'TOP '+(scryOrder.indexOf(c.uid)+1):'BOTTOM':q.kind==='recover'?'RETURN TO HAND':'DISCARD'}</strong>${card(def(c))}</button></div>`).join('')}</div></section>`;
}
function schedulePace(){clearTimeout(paceTimer);if(busy||!autoFlow||screen!=='game'||!g||mode==='hotseat'||mode==='online'&&viewer!==0||g.s.prompt||dialog.open||document.hidden||!['reveal','result'].includes(g.s.phase))return;const snapshot=g.s,phase=snapshot.phase,round=snapshot.round,reveal=snapshot.reveal,attack=snapshot.attackIndex;paceTimer=setTimeout(()=>{if(g?.s!==snapshot||g.s.phase!==phase||g.s.round!==round||g.s.reveal!==reveal||g.s.attackIndex!==attack||dialog.open||document.hidden)return;action(()=>g.advance());},phase==='reveal'?1600:1800);}

function playedCardPanel(){if(recentPlayGame!==g){recentPlayGame=g;recentPlays=[];}const s=g.s;if(['program','shop','reveal','tempo'].includes(s.phase))return '';const reaction=s.lastReaction&&!['result','over'].includes(s.phase),i=reaction?s.lastReaction.player:s.active,id=reaction?s.lastReaction.id:s.mains[i]?.id;if(i===null||!id)return '';if(reaction&&s.lastReaction.ability)return `<aside class="stage-played from-you" role="status"><p>${short(s.players[i].hero)} · HERO ABILITY</p><strong>${esc(s.lastReaction.ability)}</strong><p>${esc(s.lastReaction.effect)}</p></aside>`;const historyKey=`${s.round}-${s.reveal}-${s.attackIndex}-${s.playSerial}-${reaction?'reaction':'attack'}`;if(recentPlays[0]?.key!==historyKey){recentPlays.unshift({key:historyKey,i,id});recentPlays=recentPlays.slice(0,3);}const prior=recentPlays[1];const c=def(id),a=artLayout(c),kind=reaction?c.kind==='Loot'?'LOOT':'REACTION':['result','over'].includes(s.phase)?'ATTACK RESOLVED':'ATTACK ACTIVE';return `<aside class="stage-played ${i===viewer?'from-you':'from-rival'}" data-play-key="${s.round}-${s.reveal}-${s.attackIndex}-${s.playSerial}-${kind}" aria-label="Most recently played card"><p>${i===viewer?'YOU':short(s.players[i].hero).toUpperCase()} · ${kind}</p><button data-inspect="${c.id}" aria-label="Inspect last played card: ${esc(c.name)}"><span class="stage-played-head"><span class="stage-played-art"><span class="c-art-image" style="background-image:url('${esc(c.art)}');background-size:${a.cols*100}% ${a.rows*100}%;background-position:${a.x}% ${a.y}%;aspect-ratio:${a.ratio}"></span></span><strong>${esc(c.name)}</strong></span><span class="stage-played-effect">${esc(reaction?c.reactionText:c.attackText)}</span><small>Click to inspect card</small></button>${prior?`<button class="stage-previous-play" data-inspect="${prior.id}"><small>PREVIOUS · ${prior.i===viewer?'YOU':short(s.players[prior.i].hero)}</small>${esc(def(prior.id).name)}</button>`:''}</aside>`;}
function table(){const s=g.s;if(mode==='hotseat'){const actor=privateActor();if(actor>=0){const key=String(actor);if(privateKey!==key){app.innerHTML=`<section class="privacy"><p class="eyebrow">PASS THE DEVICE · PRIVATE HAND</p><h1>${short(s.players[actor].hero)}, your turn.</h1><p>${s.phase==='program'?'Commit two Attacks.':s.phase==='reaction'?'Play a reaction or pass.':s.prompt?'Choose your move or payment.':'Buy Loot or save your Coins.'}</p><button class="primary" data-action="ready">Show my choices →</button></section>`;return;}viewer=actor;}}
 const p=s.players[viewer],planning=s.phase==='program',selectable=planning&&!s.committed[viewer],q=s.prompt,canMove=['move','wind-place','wind-replace'].includes(q?.kind)&&q.player===viewer,reacting=s.phase==='reaction',canReact=reacting&&s.turn===viewer,attacks=g.hand(viewer,'Attack'),reactions=g.hand(viewer,'Reaction');
 const handEntries=[...p.hand.map(c=>({c,uid:c.uid,loot:false})),...p.loot.map((id,k)=>({c:def(id),uid:'loot-'+k,loot:true}))],f=['reaction','resolve'].includes(s.phase)&&s.active!==null&&!(q?.kind==='move'&&q.player===s.active)?forecast(g):null;
 const revealed=s.mains.some(Boolean)?s.mains.map((c,i)=>!c?`<div class="od-empty-attack">${i===viewer?'YOU':short(s.players[i].hero)} · NO ATTACK</div>`:`<div data-reveal-player="${i}" class="r-revealed ${s.active===i&&s.phase!=='result'&&s.phase!=='over'?'t-active':s.active!==null&&s.active!==i&&s.order.indexOf(i)>s.attackIndex?'t-waiting':s.active!==null?'t-resolved':''}"><p><b>${i===viewer?'YOU':short(s.players[i].hero).toUpperCase()}</b><span>${s.active===i?s.phase==='result'||s.phase==='over'?'RESOLVED':'ACTIVE':s.order.indexOf(i)<s.attackIndex?'RESOLVED':'WAITING'} · ϟ${g.speed(i)}</span></p><button class="stage-inspect" data-inspect="${c.id}" aria-label="Read ${esc(def(c).name)}">${card(def(c),{small:true,context:'attack'})}</button></div>`).join(''):'';
 app.innerHTML=`<section class="r-battle od-phase-${s.phase}"><div class="r-huds">${hud(0)}<div class="r-round"><p class="eyebrow">COMMIT · REACT · STRIKE</p><h1>ROUND ${s.round}</h1><p>✦ ${short(s.players[s.edge].hero)} holds Edge</p><span>${planning?'TWO SECRET ATTACKS':s.phase==='shop'?'REFILL':'PAIR '+(s.reveal+1)+' · ATTACK '+(s.attackIndex+1)}${s.round>=10?' · DEATH −'+Math.min(18,s.round-8):''}</span></div>${hud(1)}</div>${flowPanel()}${playedCardPanel()}<div class="r-clash ${planning?'planning':''}">${planning?`${plan(0)}<div class="r-clash-title"><b>Commit attacks.<br>Keep your answers.</b></div>${plan(1)}`:choicePanel()||revealed||'<div class="r-clash-title"><b>Fresh cards.<br>New trouble.</b></div>'}</div><div class="r-arena" aria-label="Eight-space arena"><div class="r-distance">↔ <b>${Math.abs(s.players[0].pos-s.players[1].pos)}</b> spaces</div>${s.players.map((p,i)=>`${p.ultimate&&p.hero==='RAV'&&Number.isInteger(p.shadowPos)?`<button class="r-fighter ls-shadow ${p.shadowPos===p.pos?'ls-overlap':''} ${p.shadowPos>s.players[1-i].pos?'rival':''}" style="--fighter-position:${(p.shadowPos-.5)/8*100}%;left:${(p.shadowPos-.5)/8*100}%" ${i===viewer?'data-action="last-stand"':'data-guide="RAV"'} ${i===viewer&&!g.canLastStand(i)?'disabled':''} aria-label="Raven shadow on space ${p.shadowPos}${i===viewer?'; swap once per round':''}"><img src="${art('RAV')}" alt="Raven’s black silhouette"><b class="ls-label">SHADOW · ${p.shadowUsed?'USED':'READY'}</b></button>`:''}<button class="r-fighter ${p.pos>s.players[1-i].pos?'rival':''} ${p.ultimate?'ls-on ls-'+p.hero:''}" style="--fighter-position:${(p.pos-.5)/8*100}%;left:${(p.pos-.5)/8*100}%" data-guide="${p.hero}" data-player="${i}" aria-label="${esc(p.name)} on space ${p.pos}${p.ultimate?'; Last Stand active':''}; view abilities"><img src="${fighterArt(p)}" alt="${esc(p.name)}${p.ultimate?' · Last Stand':''}">${p.ultimate?`<b class="ls-label">LAST STAND</b>`:''}${p.pinned?'<b class="ls-pin">PINNED</b>':''}<span></span></button>`).join('')}<div class="r-lane">${Array.from({length:8},(_,k)=>k+1).map(v=>`<button class="${s.players.some(p=>p.pos===v)?'occupied':''} ${canMove&&q.choices.includes(v)?'target':''} ${f?.spaces.includes(v)?'t-threatened':''}" data-space="${v}" ${canMove&&q.choices.includes(v)?'':'disabled'} aria-label="Arena space ${v}${canMove&&q.kind==='move'&&s.players[q.player].pos===v?'; stay':''}${f?.spaces.includes(v)?'; threatened by active attack':''}"><b>${v}</b>${s.players.map((p,i)=>p.wind?.includes(v)?`<span class="core-wind-marker owner-${i}" title="${esc(p.name)} Wind Current">${tokenIcon('MEI')}</span>`:'').join('')}${v===1||v===8?'<small>WALL</small>':''}</button>`).join('')}</div></div><p class="r-notice" aria-live="polite">${esc(s.notice)}</p>${s.preparedReveal?`<div class="x-prepared">✦ ${short(s.players[s.preparedReveal.player].hero)} prepared <button data-inspect="${s.preparedReveal.id}">${esc(def(s.preparedReveal.id).name)}</button> · ${s.preparedReveal.attack?'+2 damage · ignore 2 Block':'Range starts at 1 · +2 maximum Range'}</div>`:''}${!planning&&s.phase!=='shop'&&s.trail.length?`<div class="t-trail" aria-label="Recent exchange">${s.trail.map(t=>`<span>${esc(t)}</span>`).join('')}</div>`:''}${refillPanel()}<div class="r-bottom"><div class="r-hand-zone">${planning||reacting||s.phase==='shop'?`<p class="eyebrow r-hand-label">YOUR HAND · ${p.hand.length} CARDS${p.loot.length?' + '+p.loot.length+' LOOT':''} · ${planning?selectable?'CHOOSE YOUR ATTACKS':'ATTACKS LOCKED':reacting?canReact?'PLAY A REACTION OR LOOT':'WAIT FOR YOUR TURN':'READY FOR NEXT ROUND'}</p><p class="t-reserve-note">${planning?'Use a dual card as an Attack now, or keep its Reaction for the exchange. Loot stays ready in your hand.':'Keep unused cards. Loot is separate from your normal draw and hand limit.'}</p><div class="r-hand od-single-hand c-fan" style="--hand-count:${handEntries.length};--hand-gaps:${Math.max(1,handEntries.length-1)}">${handEntries.map(({c,uid,loot},cardIndex)=>{const usable=loot?reacting&&g.canPlay(viewer,c.id):planning?g.isAttack(c)&&selectable:reacting&&g.canPlay(viewer,c),reason=s.phase==='shop'?'Ready for next round':loot?reacting?unavailableReason(g,viewer,c.id):'Play Loot during a reaction window':planning?!g.isAttack(c)?'Reaction only · keep in hand':!selectable?'Waiting for rival':'':unavailableReason(g,viewer,c);return `<div class="od-hand-card ${!loot&&selected.includes(uid)?'c-selected':''}" style="${fanStyle(cardIndex,handEntries.length)}">${card(def(c),{uid,select:true,number:loot?0:selected.indexOf(uid)+1,disabled:!usable,reason,context:loot?'reaction':planning?'plan':'reaction'})}<button class="quiet od-read-card" data-inspect="${c.id}" aria-label="Read ${esc(def(c).name)}">Read card</button></div>`;}).join('')}</div>`:''}</div></div><div class="stage-tools"><button data-action="menu" aria-label="Open battle menu">☰ <span>Menu</span></button><button data-action="market" aria-label="Open Loot market">✦ <span>Market</span><small>2 ●</small></button></div><button class="stage-deck" data-action="my-deck" aria-label="Inspect your deck"><span>✦</span><b>${p.deck.length}</b><small>DRAW PILE</small></button><span class="stage-connection">${mode==='online'?connected?'● Online':'Reconnecting…':'● Saved'} · ${p.discard.length} discarded</span></section>`;
}
function announceLastStand(){
 if(!g||screen!=='game'){lastStandGame=null;lastStandSeen=null;return;}
 const players=g.s.players;if(lastStandGame!==g){lastStandGame=g;lastStandSeen=players.map(p=>!!p.ultimate);return;}
 const changed=lastStandTransitions(lastStandSeen,players);lastStandSeen=players.map(p=>!!p.ultimate);
 if(!changed.length)return;
 let live=document.getElementById('last-stand-announcement');if(!live){live=document.createElement('div');live.id='last-stand-announcement';live.className='ls-live-announcement';live.setAttribute('role','status');live.setAttribute('aria-live','polite');document.body.append(live);}
 live.textContent=changed.map(i=>`${players[i].name}: LAST STAND! ${hero(players[i].hero).ultimate.name}. ${lastStandStatus(players[i])}`).join(' ');
 if(!matchMedia('(prefers-reduced-motion: reduce)').matches)for(const i of changed){const panel=document.querySelector(`[data-hud-player="${i}"]`);panel?.animate([{filter:'brightness(1)',boxShadow:'0 0 0 0 #ffe6a400'},{filter:'brightness(1.6)',boxShadow:'0 0 50px 8px #ffe6a480',offset:.25},{filter:'brightness(1)',boxShadow:'0 0 25px 0 #ffe6a420'}],{duration:1400,easing:'ease-out'});}
 audio.play('reveal');
}
function render(){const stageBefore=captureStage(app);document.body.classList.toggle('in-battle',screen==='game');audio.setBattle(screen==='game');if(screen==='setup')setup();else if(screen==='lobby')renderLobby();else table();if(dialog.open&&content.querySelector('.loot-market')&&g){const stash=content.querySelector('[data-stash]')?.dataset.stash==='true';content.innerHTML=marketPanel(stash);}animateStage(app,stageBefore,g?.s,screen==='game',{card:def,sound:kind=>audio.play(kind)});announceLastStand();if(g&&screen==='game'){const s=g.s,key=s.round+'-'+s.reveal+'-'+s.phase;if(key!==lastSound){if(s.phase==='reveal')audio.play('reveal');if(s.phase==='over')audio.play('victory');lastSound=key;}lastHP=s.players.map(p=>p.hp);}scheduleBot();schedulePace();}
function save(){if(g&&mode!=='online')try{localStorage.setItem(SAVE,JSON.stringify(g.s));}catch{}}
function syncSelection(){if(!g)return;const s=g.s;selected=s.phase==='program'&&!s.committed[viewer]?selected.filter(u=>s.players[viewer].hand.some(c=>c.uid===u)):[];if(s.phase!=='reaction'||s.turn!==viewer)lootSelected=null;}
async function action(fn){if(busy)return;busy=true;try{await fn();syncSelection();save();render();}catch(e){toast(e.message);render();}finally{busy=false;scheduleBot();schedulePace();}}
function scheduleBot(){clearTimeout(botTimer);if(busy||screen!=='game'||mode!=='solo'||!g)return;const s=g.s;let fn=null;if(s.phase==='program'&&!s.committed[1])fn=()=>{g.aiPrepare(1);g.commit(1,g.aiPlan(1));};else if(s.prompt?.player===1)fn=()=>g.choose(1,g.aiChoice(1));else if(s.phase==='reaction'&&s.turn===1)fn=()=>{const a=g.aiReact(1);return a.action==='ability'?g.useHeroAbility(1,a.uid):a.action==='pass'?g.pass(1):a.action==='last-stand'?g.useLastStand(1,g.s.players[1].hero==='FRA'?g.aiShop(1):'blind'):a.action==='loot'?g.playLoot(1,a.card):g.react(1,a.uid);};else if(s.phase==='shop'&&s.shopTurn===1)fn=()=>g.shop(1,true,g.aiShop(1));if(fn)botTimer=setTimeout(()=>action(fn),1200);}
function enterOnline(snap,token){g?.close?.();g=OnlineGame.connect(data,snap,token,{onUpdate:()=>{syncSelection();render();},onConnection:v=>{connected=v;},onError:e=>toast(e.message)});viewer=g.seat;mode='online';screen='game';render();}
function renderLobby(){const url=new URL(location.href);url.hash=new URLSearchParams({room:lobby.room.id,invite:lobby.invite,hero:lobby.room.heroes[0]==='SMA'?'ALF':'SMA'});app.innerHTML=`<section class="privacy"><p class="eyebrow">PRIVATE ONLINE DUEL</p><h1>Bring your rival.</h1><p>You chose ${short(lobby.room.heroes[0])}. Your friend can choose any of the ten Heroes, including the same Hero, and build their own 24-card deck.</p><label>Private invite link<input class="r-invite" aria-label="Private invite link" readonly value="${esc(url.href)}"></label><button class="primary" data-action="copy">Copy invite</button><p>${connected?'Waiting for your rival…':'Reconnecting…'}</p><button data-action="new">Back to setup</button></section>`;}
async function pollLobby(){if(screen!=='lobby')return;const room=lobby.room.id;try{const snap=await readOnline(room,lobby.token);if(screen!=='lobby'||lobby?.room.id!==room)return;connected=true;if(snap.game){enterOnline(snap,lobby.token);return;}lobby={...lobby,...snap};}catch(e){connected=false;if([401,404,410].includes(e.status)){screen='setup';toast(e.message);render();return;}}renderLobby();pollTimer=setTimeout(pollLobby,1500);}
async function startOnline(){const link=invitation(),saved=link.room&&savedSeat(link.room);let snap;if(saved)snap={...await readOnline(link.room,saved.token),token:saved.token,invite:saved.invite};else if(link.room&&link.invite)snap=await joinOnline(link.room,link.invite,{hero:ids[0],deck:decks[0],fury:furies[0],loot:lootPicks[0]});else snap=await createOnline({hero:ids[0],deck:decks[0],fury:furies[0],loot:lootPicks[0]});history.replaceState(null,'','#'+new URLSearchParams({room:snap.room.id}));if(snap.game)enterOnline(snap,snap.token);else{lobby=snap;screen='lobby';pollLobby();}}
document.addEventListener('click',async e=>{const t=e.target.closest('button');if(!t||t.disabled)return;if(t.dataset.abilityCard){await action(async()=>{await g.useHeroAbility(viewer,t.dataset.abilityCard);selected=selected.filter(uid=>g.s.players[viewer].hand.some(c=>c.uid===uid));dialog.close();});return;}if(t.dataset.lootPick){const a=lootPicks[editor],k=a.indexOf(t.dataset.lootPick);if(k>=0)a.splice(k,1);else if(a.length<6)a.push(t.dataset.lootPick);else toast('Choose six: remove an item first.');render();return;}if(t.dataset.marketBuy){const selection=t.dataset.marketBuy,stash=t.dataset.stash==='true';await action(async()=>{if(stash)await g.useLastStand(viewer,selection);else await g.shop(viewer,true,selection);dialog.close();});return;}if(t.dataset.guide){guide(t.dataset.guide,t.dataset.player!==undefined?Number(t.dataset.player):undefined);return;}if(t.dataset.inspect){inspect(t.dataset.inspect);return;}if(t.dataset.hero){ids[editor]=t.dataset.hero;const saved=loadDraft(ids[editor],editor);decks[editor]=[...saved.deck];furies[editor]=saved.fury;buildIds[editor]=saved.build;lootPicks[editor]=[...saved.loot];render();return;}if(t.dataset.fury){furies[editor]=t.dataset.fury;render();return;}if(t.dataset.mode){mode=t.dataset.mode;editor=0;render();return;}if(t.dataset.editor!==undefined){editor=Number(t.dataset.editor);render();return;}if(t.dataset.draft){const list=decks[editor];buildIds[editor]='custom';if(t.dataset.delta==='1')list.push(t.dataset.draft);else list.splice(list.indexOf(t.dataset.draft),1);render();return;}if(t.dataset.card){const id=t.dataset.card;if(matchMedia('(hover: none)').matches&&touchCard!==id){document.querySelector('.stage-touch-preview')?.classList.remove('stage-touch-preview');touchCard=id;t.closest('.od-hand-card')?.classList.add('stage-touch-preview');toast('Tap this card again to play it.');return;}touchCard=null;if(id.startsWith('loot-')){const cardId=g.s.players[viewer].loot[Number(id.slice(5))];await action(()=>g.playLoot(viewer,cardId));return;}const c=g.s.players[viewer].hand.find(c=>c.uid===id);if(!c)return;if(g.s.phase==='reaction'){await action(()=>g.react(viewer,id));return;}if(!g.isAttack(c))return;const k=selected.indexOf(id);if(k>=0)selected.splice(k,1);else if(selected.length<g.requiredAttacks(viewer))selected.push(id);else{toast('Two attacks chosen. Click one to return it first.');return;}audio.play('card');render();return;}if(t.dataset.space){await action(()=>g.choose(g.s.prompt.player,Number(t.dataset.space)));return;}if(t.dataset.choiceIndex!==undefined){await action(()=>g.choose(viewer,g.s.prompt.choices[Number(t.dataset.choiceIndex)]));return;}if(t.dataset.scryUid){const k=scryOrder.indexOf(t.dataset.scryUid);if(k<0)scryOrder.push(t.dataset.scryUid);else scryOrder.splice(k,1);render();return;}
 switch(t.dataset.action){case'hero-ability':abilityPicker();break;case'menu':battleMenu();break;case'sound':$('#sound-btn').click();battleMenu();break;case'mix':$('#audio-settings-btn').click();break;case'fullscreen':$('#fullscreen-btn').click();break;case'pace':dialog.close();autoFlow=!autoFlow;try{localStorage.setItem('brawl2-flow',autoFlow?'on':'off');}catch{}render();break;case'scry-confirm':await action(()=>g.choose(viewer,scryOrder.join(',')));break;case'start':await action(async()=>{if(mode==='online'){await startOnline();return;}g?.close?.();g=new Brawl2(data,{mode,heroes:ids,decks,furies,lootPicks});viewer=0;privateKey=null;screen='game';lastHP=null;window.scrollTo(0,0);});break;case'resume':await action(()=>{g=Brawl2.restore(data,JSON.parse(localStorage.getItem(SAVE)));mode=g.s.mode;viewer=0;privateKey=null;screen='game';window.scrollTo(0,0);});break;case'commit':await action(()=>g.commit(viewer,[...selected]));break;case'swap':selected.reverse();render();break;case'advance':await action(()=>g.advance());break;case'last-stand':if(g.s.players[viewer].hero==='FRA')modal(marketPanel(true));else await action(()=>g.useLastStand(viewer));break;case'market':modal(marketPanel());break;case'pass':await action(()=>g.pass(viewer));break;case'buy':await action(()=>g.shop(viewer,true));break;case'save-coins':dialog.close();await action(()=>g.shop(viewer,false));break;case'log':modal(`<p class="eyebrow">THE STORY SO FAR</p><h2>Battle log</h2><ol class="stage-log">${g.s.log.map(t=>`<li>${esc(t)}</li>`).join('')}</ol>`);break;case'rules':rules();break;case'random':{const d=Brawl2.randomLoadout(data,ids[editor]);decks[editor]=d.deck;furies[editor]=d.fury;buildIds[editor]='custom';render();break;}case'clear-deck':decks[editor]=[];buildIds[editor]='custom';render();break;case'view-draft':viewDeck(decks[editor],furies[editor]);break;case'my-deck':viewDeck(g.s.players[viewer].loadout,g.s.players[viewer].furyId);break;case'ready':{const i=privateActor();viewer=i;privateKey=String(i);selected=[];lootSelected=null;render();break;}case'new':dialog.close();g?.close?.();g=null;clearTimeout(pollTimer);clearTimeout(botTimer);screen='setup';selected=[];lootSelected=null;lobby=null;privateKey=null;lastHP=null;history.replaceState(null,'',location.pathname);render();break;case'copy':try{await navigator.clipboard.writeText($('[aria-label="Private invite link"]').value);toast('Invite copied.');}catch{toast('Select the invite field and copy it.');}break;}
});
function viewDeck(list,fury){modal(`<p class="eyebrow">YOUR 24-CARD DECK · FURY SEPARATE</p><h2>Your fighting kit</h2><div class="r-library">${[...new Set(list)].map(id=>`<div><p>${list.filter(x=>x===id).length} copies</p>${card(def(id))}</div>`).join('')}</div><h3>Chosen Fury</h3>${card(def(fury))}`);}
document.addEventListener('change',e=>{if(e.target.matches('[data-build]')){const b=data.builds.find(b=>b.id===e.target.value&&b.hero===ids[editor]);if(b){decks[editor]=[...b.deck];furies[editor]=b.fury;buildIds[editor]=b.id;}else buildIds[editor]='custom';render();}});
dialog.addEventListener('close',schedulePace);$('.dialog-close').onclick=()=>dialog.close();dialog.onclick=e=>{if(e.target===dialog)dialog.close();};$('#rules-btn').onclick=rules;$('#sound-btn').textContent=audio.enabled?'Sound on':'Sound off';$('#sound-btn').onclick=()=>{audio.setEnabled(!audio.enabled);$('#sound-btn').textContent=audio.enabled?'Sound on':'Sound off';$('#sound-btn').setAttribute('aria-pressed',String(audio.enabled));};$('#audio-settings-btn').onclick=()=>modal(`<h2>Battle audio</h2><p>Existing CC0 music and combat sounds. <a href="AUDIO_CREDITS.txt" target="_blank" rel="noopener">Credits ↗</a></p><label>Music<input type="range" min="0" max="100" value="${audio.musicVolume*100}" data-volume="music"></label><label>Effects<input type="range" min="0" max="100" value="${audio.effectsVolume*100}" data-volume="effects"></label>`);document.oninput=e=>{if(e.target.dataset.volume)audio.setVolume(e.target.dataset.volume,Number(e.target.value)/100);};$('#fullscreen-btn').onclick=()=>document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen().catch(()=>toast('Fullscreen unavailable.'));document.addEventListener('pointerdown',()=>audio.unlock(),{once:true});function previewSpace(e){const button=e.target.closest('[data-space]');document.querySelector('.stage-move-preview')?.remove();if(!button||button.disabled||!g?.s.prompt||g.s.prompt.kind!=='move')return;const q=g.s.prompt,v=Number(button.dataset.space),distance=Math.abs(v-g.s.players[1-q.player].pos),hint=document.createElement('span');hint.className='stage-move-preview';hint.textContent=`Space ${v} · distance ${distance}`;const info=g.attackInfo();if(info){const inRange=info.hits.some(h=>distance>=h.min&&distance<=h.max);hint.textContent+=inRange?' · in attack range':' · out of attack range';}document.querySelector('.r-arena')?.append(hint);}
document.addEventListener('pointerover',previewSpace);document.addEventListener('focusin',previewSpace);
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!dialog.open&&screen==='game'){e.preventDefault();battleMenu();}});document.addEventListener('visibilitychange',()=>{document.body.classList.toggle('arena-paused',document.hidden);schedulePace();});$('.brand').onclick=e=>{e.preventDefault();rules();};
try{const r=await fetch('data.json',{cache:'no-store'});if(!r.ok)throw Error('The prototype card database is unavailable.');data=await r.json();for(const src of new Set([...data.cards.map(c=>c.art),...Object.values(LAST_STAND_ART)])){const img=new Image();img.src=src;cardArtCache.push(img);}const invitedHero=new URLSearchParams(location.hash.slice(1)).get('hero');if(invitation().invite&&data.heroes.some(h=>h.id===invitedHero))ids=[invitedHero,invitedHero==='SMA'?'ALF':'SMA'];try{drafts=JSON.parse(localStorage.getItem(DRAFT_SAVE)||'{}')||{};}catch{drafts={};}const savedDrafts=ids.map((id,i)=>loadDraft(id,i));decks=savedDrafts.map(d=>[...d.deck]);furies=savedDrafts.map(d=>d.fury);buildIds=savedDrafts.map(d=>d.build);lootPicks=savedDrafts.map(d=>[...d.loot]);render();canOnline=await onlineSupported();if(canOnline&&invitation().room){mode='online';if(savedSeat(invitation().room))try{await startOnline();}catch(e){toast(e.message);}}render();}catch(e){app.innerHTML=`<section class="privacy"><h1>The arena is resting.</h1><p>${esc(e.message)}</p><button onclick="location.reload()">Try again</button></section>`;}
